import { Component } from 'react'
import ReactDOMServer from 'react-dom/server'
import { connect } from 'react-redux'
// import { get as lodashGet } from 'lodash/object'
import { Container, CustomText } from '../../../../../components'
import { LANG_STRINGS } from '../../../../../lang'
import { FAQS, GOJEK_DRIVER_FAQ, JIWA_FAQS } from '../../constants'
import { FAQsStyle, CollapsableBodyStyle } from './index.style'
import { Row } from '../../../../../commonStyle/index.style'
import { AgentColorPallette } from '../../../../../configs/colorPallete'
// import { checkIsGojekDriver } from '../../../../../helpers/checkAgentTags'
import { CUSTOMER_FAQS } from '../../../../Public/Customer/constants/customerFaqs'
// import { getParamsFromUri } from '../../../../../helpers/utility'

class FAQsPage extends Component {
  state = {
    isExpand: 'content_0'
  }

  handleExpand = (value) => {
    this.setState({
      isExpand: value
    })
  }

  getTitleContainer = (title, index) => (
    <Row
      justify='space-between'
      align='center'
      className='collapsible-header'
      onClick={() => this.handleExpand(`content_${index}`)}
    >
      <CustomText
        size='14px'
        weight={700}
        className='collapsible-title'
        color={AgentColorPallette.regular}
        bottom='16px'
      >
        {title}
      </CustomText>
      {
        <CustomText
          size='16px'
          color={AgentColorPallette.regular}
          bottom='16px'
        >
          <i className={`fas ${this.state.isExpand === 'content_' + index ? 'fa-angle-up caret-rotate-down' : 'fa-angle-down caret-rotate-down'}`} />
        </CustomText>
      }
    </Row>
  )

  getContentList = (list = [], title, itemIndex) => {
    return (
      <>
        {title && (<div key={`minContentTitle_${itemIndex}`}>{title}</div>)}
        <ol className='content-list' key={`minContent_${itemIndex}`}>
          {
            list.map((item, itemIndex) => (
              <li key={`li_${itemIndex}`}>
                <div
                  dangerouslySetInnerHTML={{
                    __html: item
                  }}
                />
              </li>
            ))
          }
        </ol>
      </>
    )
  }

  getContentBody = (body, index) => {
    return (
      <CollapsableBodyStyle
        dangerouslySetInnerHTML={{
          __html: body
        }}
        open={this.state.isExpand === `content_${index}`}
      />
    )
  }

  getContentObjBody = (body, index) => {
    if (Array.isArray(body)) {
      const ContentHTML = (
        <>
          {
            body.map((item, itemIndex) => this.getContentList(item.content, item.title, itemIndex))
          }
        </>
      )
      return this.getContentBody(
        ReactDOMServer.renderToStaticMarkup(ContentHTML),
        index
      )
    }

    const { title, content } = body
    let element = title ? `${title}<br/>` : ''
    const bodyHtml = ReactDOMServer.renderToStaticMarkup(this.getContentList(content))
    element = `${element}${bodyHtml}`
    return (
      <>
        {
          this.getContentBody(
            element,
            index
          )
        }
      </>
    )
  }

  getAnsBody = (faq, index) => {
    const { content, subContent, bottomContent = '' } = faq
    let element = content ? `${content}<br/>` : ''
    const subContentHtml = ReactDOMServer.renderToStaticMarkup(this.getsubContentBody(subContent))
    element = `${element}${subContentHtml}${bottomContent}`
    return (
      <>
        {
          this.getContentBody(
            element,
            index
          )
        }
      </>
    )
  }

  getsubContentBody = (body) => {
    if (Array.isArray(body)) {
      return (
        <ul>
          {
            body.map((content, cIndex) => (
              <li key={`cindex_${cIndex}`}>{content}</li>
            ))
          }
        </ul>
      )
    } else if (typeof body === 'object') {
      const { title, content = [] } = body
      return (
        <div>
          {title}
          <ol className='content-list'>
            {
              content.map((item, itIndex) => {
                const { title, content: subContent = [] } = item
                return (
                  <li key={`itindex_${itIndex}`}>
                    <div
                      dangerouslySetInnerHTML={{
                        __html: title
                      }}
                    />
                    {
                      this.getsubContentBody(subContent)
                    }
                  </li>
                )
              })
            }
          </ol>
        </div>
      )
    }
    return null
  }

  render () {
    let faqsData = [
      ...FAQS,
      ...GOJEK_DRIVER_FAQ,
      ...JIWA_FAQS
    ]
    const isCustomer = window.location.pathname.includes('/customer/faqs')
    if (isCustomer) {
      faqsData = CUSTOMER_FAQS
    }

    return (
      <Container
        title={LANG_STRINGS.faqs}
        showInnerHeader
        displayBackButton
        hideBottomTabs
        className='bg-white'
      >
        <FAQsStyle>
          {
            faqsData.map((faq, index) => {
              if (typeof faq.content === 'string') {
                return (
                  <div className='accordion-body' key={`acord_${index + 1}`}>
                    {this.getTitleContainer(faq.title, index)}
                    {this.getAnsBody(faq, index)}
                  </div>
                )
              } else if (typeof faq.content === 'object') {
                return (
                  <div className='accordion-body' key={`acord_${index + 1}`}>
                    {this.getTitleContainer(faq.title, index)}
                    {this.getContentObjBody(faq.content, index)}
                  </div>
                )
              }
              return null
            })
          }
        </FAQsStyle>
      </Container>
    )
  }
}

export default connect(
  state => ({
    agentDetails: state.User.agentDetails
  }),
  {

  }
)(FAQsPage)
